/**
 * PlutusV3 script taking an integer threshold parameter. It always succeeds,
 * but costs more when the transaction fee is at or above the threshold:
 *
 * ```
 * \threshold ctx ->
 *   if unIData(fee(ctx)) < unIData(threshold)
 *     then 64 nested sha2_256 calls
 *     else 256 nested sha2_256 calls
 * ```
 *
 * Apply the threshold with `applyParamsToScript`.
 */
export const feeThresholdV3Script: Script = {
  type: "PlutusV3",
  script:
    "",
};
